njs_regexp_escape(njs_vm_t *vm, nxt_str_t *text)
{
    size_t      brackets, zeros;
    u_char      *p, *dst, *start, *end;
    nxt_bool_t  in;

    start = text->start;
    end = text->start + text->length;

    in = 0;
    zeros = 0;
    brackets = 0;

    for (p = start; p < end; p++) {

        switch (*p) {
        case '[':
            in = 1;
            break;

        case ']':
            if (!in) {
                brackets++;
            }

            in = 0;
            break;

        case '\\':
            p++;

            if (p == end || *p != '\0') {
                break;
            }

            /* Fall through. */

        case '\0':
            zeros++;
            break;
        }
    }

    if (!brackets && !zeros) {
        return NXT_OK;
    }

    text->length = text->length + brackets + zeros * nxt_length("\\u0000");

    text->start = nxt_mp_alloc(vm->mem_pool, text->length);
    if (nxt_slow_path(text->start == NULL)) {
        njs_memory_error(vm);
        return NXT_ERROR;
    }

    in = 0;
    dst = text->start;

