            }

            if (*p != '\0') {
                break;
            }

            /* Fall through. */

        case '\0':
            dst = nxt_cpymem(dst, "\\u0000", 6);
            continue;
        }

        *dst++ = *p;
    }

done:

    text->length = dst - text->start;

    return NXT_OK;
}

