static void
aodv_extension(netdissect_options *ndo,
               const struct aodv_ext *ep, u_int length)
{
	const struct aodv_hello *ah;

	ND_TCHECK(*ep);
	switch (ep->type) {
	case AODV_EXT_HELLO:
		ah = (const struct aodv_hello *)(const void *)ep;
		ND_TCHECK(*ah);
		if (length < sizeof(struct aodv_hello))
			goto trunc;
		if (ep->length < 4) {
			ND_PRINT((ndo, "\n\text HELLO - bad length %u", ep->length));
			break;
		}
		ND_PRINT((ndo, "\n\text HELLO %ld ms",
		    (unsigned long)EXTRACT_32BITS(&ah->interval)));
		break;

	default:
		ND_PRINT((ndo, "\n\text %u %u", ep->type, ep->length));
		break;
	}
	return;

trunc:
	ND_PRINT((ndo, " [|hello]"));
}

annotation:
[Mandatory] ID:
CVE-2017-13002

[Mandatory] Title: CVE-2017-13002 / CWE-125:
AODV buffer over-read

[Optional] Disclosure / Patch Dates:
Initial advisory: 2017-09-14 — Patch release: Not available in input

[Optional] Affected products/versions:
Not available in input

The Vulnerability
[Optional] CWE/CVE Number and description:
CWE-125
[Mandatory] Summary:
The vulnerability is in the aodv_extension function of tcpdump, which processes AODV (Ad hoc On-Demand Distance Vector) protocol extensions. The flaw is triggered when processing a crafted AODV packet, as the function reads the ep->type field without first verifying that the input buffer is large enough to contain the aodv_ext structure. This can lead to an out-of-bounds read, making the issue exploitable for information disclosure or a potential denial of service.
[Mandatory] Root cause:
The function reads the ep->type field before performing a bounds check on the ep pointer.
[Mandatory] Attack Surface:
Network packet parser (tcpdump)
[Mandatory] Impact Summary:
Information disclosure / Denial of Service
[Optional] Trigger / Attack vector:
Crafted AODV packet on the network
[Mandatory] Key code/struct excerpt (minimal):
static void
aodv_extension(netdissect_options *ndo,
               const struct aodv_ext *ep, u_int length)
{
	const struct aodv_hello *ah;

	ND_TCHECK(*ep);
	switch (ep->type) {
	case AODV_EXT_HELLO:
