files.print-rx.c:
static void
ubik_print(netdissect_options *ndo,
           register const u_char *bp)
{
	int ubik_op;
	int32_t temp;

	/*
	 * Print out the afs call we're invoking.  The table used here was
	 * gleaned from ubik/ubik_int.xg
	 */

	ubik_op = EXTRACT_32BITS(bp + sizeof(struct rx_header));

	ND_PRINT((ndo, " ubik call %s", tok2str(ubik_req, "op#%d", ubik_op)));

	/*
	 * Decode some of the arguments to the Ubik calls
	 */

	bp += sizeof(struct rx_header) + 4;

	switch (ubik_op) {
		case 10000:		/* Beacon */
			ND_TCHECK2(bp[0], 4);
			temp = EXTRACT_32BITS(bp);
			bp += sizeof(int32_t);
			ND_PRINT((ndo, " syncsite %s", temp ? "yes" : "no"));
			ND_PRINT((ndo, " votestart"));
			DATEOUT();
			ND_PRINT((ndo, " dbversion"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			break;
		case 10003:		/* Get sync site */
			ND_PRINT((ndo, " site"));
			UINTOUT();
			break;
		case 20000:		/* Begin */
		case 20001:		/* Commit */
		case 20007:		/* Abort */
		case 20008:		/* Release locks */
		case 20010:		/* Writev */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			break;
		case 20002:		/* Lock */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " file"));
			INTOUT();
			ND_PRINT((ndo, " pos"));
			INTOUT();
			ND_PRINT((ndo, " length"));
			INTOUT();
			ND_TCHECK_32BITS(bp);
			temp = EXTRACT_32BITS(bp);
			bp += sizeof(int32_t);
			tok2str(ubik_lock_types, "type %d", temp);
			break;
		case 20003:		/* Write */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " file"));
			INTOUT();
			ND_PRINT((ndo, " pos"));
			INTOUT();
			break;
		case 20005:		/* Get file */
			ND_PRINT((ndo, " file"));
			INTOUT();
			break;
		case 20006:		/* Send file */
			ND_PRINT((ndo, " file"));
			INTOUT();
			ND_PRINT((ndo, " length"));
			INTOUT();
			ND_PRINT((ndo, " dbversion"));
			UBIK_VERSIONOUT();
			break;
		case 20009:		/* Truncate */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " file"));
			INTOUT();
			ND_PRINT((ndo, " length"));
			INTOUT();
			break;
		case 20012:		/* Set version */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " oldversion"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " newversion"));
			UBIK_VERSIONOUT();
			break;
		default:
			;
	}

	return;

trunc:
	ND_PRINT((ndo, " [|ubik]"));
}

annotation:
[Mandatory] ID:
CVE-2017-13049

[Mandatory] Title: CVE-2017-13049 / CWE-125:
Buffer over-read

[Optional] Disclosure / Patch Dates:
Initial advisory: 2017-09-14 — Patch release: Not available in input

[Optional] Affected products/versions:
Not available in input

The Vulnerability
[Optional] CWE/CVE Number and description:
CWE-125
[Mandatory] Summary:
The vulnerability is in the `ubik_print` function within `print-rx.c`. It is triggered when processing a Ubik packet with operation code 20002 (Lock). The function reads a 32-bit integer from the packet buffer without first verifying that enough bytes remain, leading to an out-of-bounds read past the end of the captured packet data.
[Mandatory] Root cause:
Missing bounds check before reading a 32-bit value from the packet buffer.
[Mandatory] Attack Surface:
Network packet parser (tcpdump)
[Mandatory] Impact Summary:
Denial of service via application crash or potential information leak.
[Optional] Trigger / Attack vector:
Malformed Ubik network packet
[Mandatory] Key code/struct excerpt (minimal):
		case 20002:		/* Lock */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " file"));
			INTOUT();
			ND_PRINT((ndo, " pos"));
			INTOUT();
			ND_PRINT((ndo, " length"));
			INTOUT();
			temp = EXTRACT_32BITS(bp);
			bp += sizeof(int32_t);
			tok2str(ubik_lock_types, "type %d", temp);
			break;

Exploit:

[Mandatory] Trigger surface/attack vector:
Network packet parsing

[Mandatory] Exploit primitive(s) available:
Out-of-bounds read

[Mandatory] Exploitability summary (1 sentence):
An attacker can trigger the vulnerability by sending a specially crafted network packet that is shorter than expected, causing the application to read past the buffer.

[Mandatory] Exploit script (summary, 3—6 bullets):
- Craft a Ubik packet with operation code 20002.
- Ensure the packet is truncated before the 32-bit lock type field.
- Send the packet to a system running the vulnerable version of tcpdump.
- The `ubik_print` function will attempt to read the lock type without a bounds check.
- This results in an out-of-bounds read, potentially crashing the application or leaking memory.

Fix
[Mandatory] Fix code:
		case 20002:		/* Lock */
			ND_PRINT((ndo, " tid"));
			UBIK_VERSIONOUT();
			ND_PRINT((ndo, " file"));
			INTOUT();
			ND_PRINT((ndo, " pos"));
			INTOUT();
			ND_PRINT((ndo, " length"));
			INTOUT();
			ND_TCHECK_32BITS(bp);
			temp = EXTRACT_32BITS(bp);
			bp += sizeof(int32_t);
			tok2str(ubik_lock_types, "type %d", temp);
			break;

[Mandatory] Fix summary:
The patch adds a bounds check (`ND_TCHECK_32BITS(bp)`) before reading the 32-bit lock type value to ensure the buffer contains enough data, preventing the over-read.

[Optional] Patch reference:
https://github.com/the-tcpdump-group/tcpdump/commit/aa0858100096a3490edf93034a80e66a4d61aad5
[Optional] Patch Analysis:
What did the fix do?
- Field: PatchType (bounds check added)
[Optional] Variant & Triage Guidance

[Optional] Variant analysis suggestions (2—3 bullets):
- Review other `case` blocks in `ubik_print` and similar packet-parsing functions for missing `ND_TCHECK_*` calls before data extraction.
