int InMemoryUrlProtocol::Read(int size, uint8* data) {
  if (size < 0)
    return AVERROR(EIO);

  int64 available_bytes = size_ - position_;
  if (size > available_bytes)
    size = available_bytes;

  if (size > 0) {
    memcpy(data, data_ + position_, size);
    position_ += size;
  }

  return size;
}

