static void youngcollection (lua_State *L, global_State *g) {
  GCObject **psurvival;  /* to point to first non-dead survival object */
  lua_assert(g->gcstate == GCSpropagate);
  markold(g, g->allgc, g->reallyold);
  markold(g, g->finobj, g->finobjrold);
  atomic(L);

  /* sweep nursery and get a pointer to its last live element */
  psurvival = sweepgen(L, g, &g->allgc, g->survival);
  /* sweep 'survival' and 'old' */
  sweepgen(L, g, psurvival, g->reallyold);
  g->reallyold = g->old;
  g->old = *psurvival;  /* 'survival' survivals are old now */
  g->survival = g->allgc;  /* all news are survivals */

  /* repeat for 'finobj' lists */
  psurvival = sweepgen(L, g, &g->finobj, g->finobjsur);
  /* sweep 'survival' and 'old' */
  sweepgen(L, g, psurvival, g->finobjrold);
  g->finobjrold = g->finobjold;
  g->finobjold = *psurvival;  /* 'survival' survivals are old now */
  g->finobjsur = g->finobj;  /* all news are survivals */

  sweepgen(L, g, &g->tobefnz, NULL);

  finishgencycle(L, g);
}

annotation:
[Mandatory] ID: CVE-2020-15889

[Mandatory] Title: CVE-2020-15889 / CWE-125:
Out-of-bounds read in GC

[Optional] Disclosure / Patch Dates:
Initial advisory: 2020-07-21 — Patch release: Not available in input

[Optional] Affected products/versions:
Not available in input

The Vulnerability
[Optional] CWE/CVE Number and description:
 Out-of-bounds read
[Mandatory] Summary:
 The bug is in the `youngcollection` garbage collection function. When an aged object is finalized, it is moved to the beginning of the `allgc` list, but the `markold` function was called with `g->survival` instead of `g->allgc`. This caused `markold` to miss marking the newly moved finalized objects, leading to a use-after-free or out-of-bounds read during subsequent collection cycles.
[Mandatory] Root cause:
 Incorrect list argument passed to `markold`, causing finalized objects to be unmarked and prematurely collected.
[Mandatory] Attack Surface:
Not available in input
[Mandatory] Impact Summary:
Not available in input
[Optional] Trigger / Attack vector:
Not available in input
[Mandatory] Key code/struct excerpt (minimal):
static void youngcollection (lua_State *L, global_State *g) {
  GCObject **psurvival;  /* to point to first non-dead survival object */
  lua_assert(g->gcstate == GCSpropagate);
  markold(g, g->survival, g->reallyold);
  markold(g, g->finobj, g->finobjrold);
  atomic(L);

  /* sweep nursery and get a pointer to its last live element */
  psurvival = sweepgen(L, g, &g->allgc, g->survival);
  /* sweep 'survival' and 'old' */
  sweepgen(L, g, psurvival, g->reallyold);
  g->reallyold = g->old;
  g->old = *psurvival;  /* 'survival' survivals are old now */
  g->survival = g->allgc;  /* all news are survivals */

  /* repeat for 'finobj' lists */
  psurvival = sweepgen(L, g, &g->finobj, g->finobjsur);
  /* sweep 'survival' and 'old' */
  sweepgen(L, g, psurvival, g->finobjrold);
  g->finobjrold = g->finobjold;
  g->finobjold = *psurvival;  /* 'survival' survivals are old now */
  g->finobjsur = g->finobj;  /* all news are survivals */

  sweepgen(L, g, &g->tobefnz, NULL);

