                               outp[1] == 0 && outp[2] == 0)
                            outp += 3;
                        tpos = (outp - out) / bytes_per_space;
                        newp = out + tpos * bytes_per_space;
                        if (newp > zp + 10) {   /* Output preceding bit data. */
                            if (zp > out_blk)
                                /* only false at */
                                /* beginning of line */
                                epsc_output_run(out_blk, (int)(zp - out_blk),
                                                y_mult, start_graphics,
                                                prn_stream, pass);
                            /* Tab over to the appropriate position. */
                            gp_fprintf(prn_stream, "\033D%c%c\t", tpos, 0);
                            out_blk = outp = newp;
                        }
                    } else
                        outp += y_mult;
                }
                if (outp > out_blk)
                    epsc_output_run(out_blk, (int)(outp - out_blk),
                                    y_mult, start_graphics, prn_stream, pass);

                gp_fputc('\r', prn_stream);
            }
        } while (nextcolor);
        skip = 24;
        lnum += 8 * y_mult;
    }

    /* Eject the page and reinitialize the printer */
    gp_fputs("\f\033@", prn_stream);

    gs_free(pdev->memory, (char *)out, out_size + 1, 1,
            "epsc_print_page(out)");
    gs_free(pdev->memory, (char *)in, in_size + 1, 1, "epsc_print_page(in)");
    if (gx_device_has_color(pdev))
        gs_free(pdev->memory, (char *)color_in, color_in_size + 1, 1,
                "epsc_print_page(rin)");
    return 0;
}

annotation:
[Mandatory] ID:
CVE-2020-16294

[Mandatory] Title: CVE-2020-16294 / CWE-120:
Out-of-bounds array access in epsc_print_page()

[Optional] Disclosure / Patch Dates:
Initial advisory: [2020-08-13] — Patch release: Not available in input

[Optional] Affected products/versions:
ArtifexSoftware/ghostpdl (pre-commit 89f58f1aa95b3482cadf6977da49457194ee5358)

The Vulnerability
[Optional] CWE/CVE Number and description:
CWE-120: Classic buffer overflow
[Mandatory] Summary:
The vulnerability exists in the `epsc_print_page` function where `x_dpi` is used as an index into the `graphics_modes_9` and `graphics_modes_24` arrays without bounds checking. A large value for `x_dpi` can trigger an out-of-bounds read, as demonstrated in the code excerpt where `start_graphics` is assigned from an unchecked array access.
[Mandatory] Root cause:
The root cause is the lack of bounds validation for the `x_dpi` variable before it is used as an index into the static `graphics_modes_9` and `graphics_modes_24` arrays.
[Mandatory] Attack Surface:
Ghostscript interpreter processing a crafted file with the `epsonc` device.
[Mandatory] Impact Summary:
Out-of-bounds read, potentially leading to information disclosure or denial of service.
[Optional] Trigger / Attack vector:
A crafted file processed by Ghostscript with the Epson color printer driver (`epsonc`) at a high resolution (e.g., `-r680`).
[Mandatory] Key code/struct excerpt (minimal):
    int x_dpi = (int)pdev->x_pixels_per_inch;

    char start_graphics;
    int first_pass;
    int last_pass;
    int dots_per_space; 
    int bytes_per_space;
    int skip = 0, lnum = 0, pass;

    byte *color_in;
    int color_line_size, color_in_size;
    int spare_bits;
    int whole_bits;

    int max_dpi = 60 * (
            (y_24pin) ?
            sizeof(graphics_modes_24) / sizeof(graphics_modes_24[0])
            :
            sizeof(graphics_modes_9) / sizeof(graphics_modes_9[0])
            )
            - 1;
    if (x_dpi > max_dpi) {
        return_error(gs_error_rangecheck);
    }

    in =
        (byte *) gs_malloc(pdev->memory, in_size + 1, 1,
                           "epsc_print_page(in)");
    out =
        (byte *) gs_malloc(pdev->memory, out_size + 1, 1,
                           "epsc_print_page(out)");

    start_graphics = (char)
        ((y_24pin ? graphics_modes_24 : graphics_modes_9)[x_dpi / 60]);
Exploit:

[Mandatory] Trigger surface/attack vector:
Ghostscript command-line processing a document with the epsonc device and a high-resolution option.

[Mandatory] Exploit primitive(s) available:
Out-of-bounds read.

[Mandatory] Exploitability summary (1 sentence):
The vulnerability is easily triggered by processing a file with a specific device and resolution, leading to a predictable out-of-bounds access.

[Mandatory] Exploit script (summary, 3—6 bullets):
- Use Ghostscript to process a crafted PDF or PostScript file.
- Specify the `epsonc` output device: `-sDEVICE=epsonc`.
- Set a high horizontal resolution, e.g., `-r680`, to cause `x_dpi` to exceed the array bounds.
- The `epsc_print_page` function will be invoked, leading to an out-of-bounds read from `graphics_modes_9` or `graphics_modes_24`.
- This may cause a crash or leak adjacent memory data.

Fix
[Mandatory] Fix code:
    int x_dpi = (int)pdev->x_pixels_per_inch;

    char start_graphics;
    int first_pass;
    int last_pass;
    int dots_per_space; 
    int bytes_per_space;
    int skip = 0, lnum = 0, pass;

    byte *color_in;
    int color_line_size, color_in_size;
    int spare_bits;
    int whole_bits;

    int max_dpi = 60 * (
            (y_24pin) ?
            sizeof(graphics_modes_24) / sizeof(graphics_modes_24[0])
            :
            sizeof(graphics_modes_9) / sizeof(graphics_modes_9[0])
            )
            - 1;
    if (x_dpi > max_dpi) {
        return_error(gs_error_rangecheck);
    }

    in =
        (byte *) gs_malloc(pdev->memory, in_size + 1, 1,
                           "epsc_print_page(in)");
    out =
        (byte *) gs_malloc(pdev->memory, out_size + 1, 1,
                           "epsc_print_page(out)");

    start_graphics = (char)
        ((y_24pin ? graphics_modes_24 : graphics_modes_9)[x_dpi / 60]);
[Mandatory] Fix summary:
The patch adds a bounds check on `x_dpi` before it is used as an array index. If `x_dpi` is larger than a calculated `max_dpi`, the function returns an error, preventing the out-of-bounds read.
[Optional] Patch reference:
Commit 89f58f1aa95b3482cadf6977da49457194ee5358 in ArtifexSoftware/ghostpdl repository.
[Optional] Patch Analysis:
What did the fix do?
- Field: PatchType (bounds check added)
[Optional] Variant & Triage Guidance

[Optional] Variant analysis suggestions (2—3 bullets):
- Review other device drivers for similar unchecked array accesses based on input parameters like resolution.
- Fuzz Ghostscript with various devices and non-standard resolution settings to find latent out-of-bounds issues.
- Audit all uses of `pdev->x_pixels_per_inch` and `pdev->y_pixels_per_inch` for missing validation.

[Optional] Likely variants/impact (one line):
Similar resolution-based out-of-bounds reads may exist in other printer device drivers.

