[Mandatory] Fix code:
static char *
stub_charset ()
{
  char *locale, *s, *t;

  locale = get_locale_var ("LC_CTYPE");
  if (locale == 0 || *locale == 0)
    {
      strncpy (charsetbuf, "ASCII", sizeof(charsetbuf) - 1);
      charsetbuf[sizeof(charsetbuf) - 1] = '\0';
      return charsetbuf;
    }
  s = strrchr (locale, '.');
  if (s)
    {
      strncpy (charsetbuf, s+1, sizeof(charsetbuf) - 1);
      charsetbuf[sizeof(charsetbuf) - 1] = '\0';
      t = strchr (charsetbuf, '@');
      if (t)
