            restart = true;
          }
        }

        jerry_release_value (str_val);
      }

      jerry_release_value (abort_value);
    }

    if (!restart)
    {
      break;
    }

    jerry_cleanup ();

    init_engine (flags, true, debug_port);

    ret_value = jerry_create_undefined ();
  }

  if (is_repl_mode)
  {
    const char *prompt = !no_prompt ? "jerry> " : "";
    bool is_done = false;

    while (!is_done)
    {
